```
attribute vec4 aOrb1; // a, e, i, om (deg)
attribute vec4 aOrb2; // w, ma (deg), depoch, n (deg/day)
attribute vec3 aMisc; // diam, flags, classIdx
attribute vec3 aColor;
attribute float aAlpha;
uniform float uT;      // jd - epochRef
uniform float uPx;     // pixel scale
uniform float uTime;   // for pulse
varying vec3 vColor;
varying float vAlpha;
varying float vPha;

void main(){
  float a=aOrb1.x, e=aOrb1.y, inc=aOrb1.z, om=aOrb1.w;
  float w=aOrb2.x, ma=aOrb2.y, dep=aOrb2.z, n=aOrb2.w;
  float M = radians(ma + n*(uT - dep));
  // normalize
  M = mod(M + 3.14159265, 6.2831853) - 3.14159265;
  float E = M + e*sin(M); // initial
  for(int k=0;k<8;k++){
    E = E - (E - e*sin(E) - M)/(1.0 - e*cos(E));
  }
  float xo = a*(cos(E)-e);
  float yo = a*sqrt(1.0-e*e)*sin(E);
  // rotate
  float cw=cos(radians(w)), sw=sin(radians(w));
  float ci=cos(radians(inc)), si=sin(radians(inc));
  float co=cos(radians(om)), so=sin(radians(om));
  vec3 pos;
  pos.x = (co*cw-so*sw*ci)*xo + (-co*sw-so*cw*ci)*yo;
  pos.y = (sw*si)*xo + (cw*si)*yo;
  pos.z = (so*cw+co*sw*ci)*xo + (-so*sw+co*cw*ci)*yo;
  vec4 mv = modelViewMatrix * vec4(pos,1.0);
  gl_Position = projectionMatrix * mv;
  float d = aMisc.x; // km
  float base = 1.6 + 2.4*log(d+1.0); // log size
  float pha = mod(aMisc.y, 2.0);
  base *= (1.0 + 0.5*pha);
  gl_PointSize = clamp(base * uPx * (2.0 / -mv.z), 1.5, 14.0);
  vColor = aColor; vAlpha = aAlpha; vPha = pha;
}
```
