  user-select: none;
}
.body-label.selected { color: #ffd166; font-weight: bold; }

.hidden { display: none !important; }
.hidden-ui { opacity: 0; transition: opacity 0.6s ease 0.2s; }
body.loaded .hidden-ui { opacity: 1; }

/* ---- top bar ---- */
#topbar {
  position: fixed;
  top: 0; left: 0; right: 0;
  display: flex;
  align-items: center;
  gap: 18px;
  padding: 8px 14px;
  background: linear-gradient(rgba(4, 8, 14, 0.9), rgba(4, 8, 14, 0.55) 80%, transparent);
  z-index: 10;
}
.brand { font-weight: 700; letter-spacing: 0.25em; color: #e8f4ff; }
.brand span { color: var(--accent); }
.brand.big { font-size: 22px; margin-bottom: 14px; }
#clock { min-width: 150px; }
#date-display { font-size: 16px; color: #fff; letter-spacing: 0.06em; }
#jd-display { font-size: 10px; color: var(--dim); }
#time-controls { display: flex; gap: 6px; align-items: center; }

.tbtn, .seg button, .mini {
  background: rgba(76, 201, 240, 0.08);
  border: 1px solid var(--panel-border);
  color: var(--text);
  font-family: var(--mono);
